import{_ as a,o as t,c as i,ao as n}from"./chunks/framework.CjHcmwhZ.js";const p=JSON.parse('{"title":"Benchmarking","description":"","frontmatter":{},"headers":[],"relativePath":"man/benchmarking.md","filePath":"man/benchmarking.md","lastUpdated":null}'),r={name:"man/benchmarking.md"};function s(o,e,h,c,l,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="Benchmarking" tabindex="-1">Benchmarking <a class="header-anchor" href="#Benchmarking" aria-label="Permalink to &quot;Benchmarking {#Benchmarking}&quot;">​</a></h1><p>MagmaThermoKinematics.jl was benchmarked against the thermal-kinematic codes used by the UCLA (Oscar Lovera) and Geneva (Gregor Weber, Luca Caricchi) research groups as part of the ZASSy intercomparison. Good agreement was found between the codes; the comparison, the equations solved, and the sensitivity of the results to parameters such as temperature-dependent conductivity are described in</p><ul><li>Schmitt, A.K., Sliwinski, J., Caricchi, L., Bachmann, O., Riel, N., Kaus, B.J.P., de Léon, A.C., Cornet, J., Friedrichs, B., Lovera, O., Sheldrake, T., Weber, G. (2023). Zircon age spectra to quantify magma evolution. Geosphere 19. <a href="https://doi.org/10.1130/GES02563.1" target="_blank" rel="noreferrer">https://doi.org/10.1130/GES02563.1</a></li></ul><p>The benchmark scenario is included in the repository:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;examples/Example2D_ZASSy.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Note that the thermal structure can differ substantially between models at the <em>same</em> magma flux, depending on the assumption made about where and how magma is intruded (underplating, central injection, injection through dikes). This difference is often larger than the effect of varying the material parameters.</p>',6)])])}const u=a(r,[["render",s]]);export{p as __pageData,u as default};
